public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    backtrack(nums, 0, result);
    return result;
}

private void backtrack(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        List<Integer> perm = new ArrayList<>(nums.length);
        for (int num : nums) {
            perm.add(num);
        }
        result.add(perm);
        return;
    }
    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        backtrack(nums, start + 1, result);
        swap(nums, start, i); // backtrack
    }
}

private void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to minimize candidate substrings
    String shortest = null;
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        if (s.length() < minLen) {
            minLen = s.length();
            shortest = s;
        }
    }
    if (minLen == 0) {
        return 0;
    }

    int left = 1;
    int right = minLen;
    int best = 0;

    while (left <= right) {
        int mid = (left + right) >>> 1;
        boolean found = false;
        // Enumerate all substrings of length mid from the shortest string
        for (int i = 0; i + mid <= shortest.length(); i++) {
            String sub = shortest.substring(i, i + mid);
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (String other : strings) {
                if (other == null) {
                    ok = false;
                    break;
                }
                if (other.indexOf(sub) >= 0 || other.indexOf(rev) >= 0) {
                    continue;
                } else {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                found = true;
                break;
            }
        }
        if (found) {
            best = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return best;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int depositCount = 0;
    // 8-direction deltas
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                depositCount++;
                // iterative DFS using stack
                int[] stackR = new int[rows * cols];
                int[] stackC = new int[rows * cols];
                int top = 0;
                stackR[0] = r;
                stackC[0] = c;
                visited[r][c] = true;
                while (top >= 0) {
                    int cr = stackR[top];
                    int cc = stackC[top];
                    top--;
                    for (int dir = 0; dir < 8; dir++) {
                        int nr = cr + dr[dir];
                        int nc = cc + dc[dir];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            top++;
                            stackR[top] = nr;
                            stackC[top] = nc;
                        }
                    }
                }
            }
        }
    }
    return depositCount;
}

