}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        // Basic validation
        if (n <= 0 || start == null || end == null || paths == null
                || start.length == 0 || end.length == 0) {
            return "cannot be travelled";
        }
        // We only use the first element as the node id if multiple are provided
        int startNode = start[0];
        int endNode = end[0];

        if (startNode == endNode) {
            return "can be travelled";
        }

        // Build adjacency map
        java.util.Map<Integer, java.util.List<Integer>> adj = new java.util.HashMap<>();

        for (int[] edge : paths) {
            if (edge == null || edge.length < 2) {
                continue; // skip invalid edge definitions
            }
            int u = edge[0];
            int v = edge[1];
            adj.computeIfAbsent(u, k -> new java.util.ArrayList<>()).add(v);
            adj.computeIfAbsent(v, k -> new java.util.ArrayList<>()).add(u);
        }

        // BFS
        java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
        java.util.Set<Integer> visited = new java.util.HashSet<>();

        queue.offer(startNode);
        visited.add(startNode);

        while (!queue.isEmpty()) {
            int node = queue.poll();
            java.util.List<Integer> neighbors = adj.getOrDefault(node, java.util.Collections.emptyList());
            for (int nb : neighbors) {
                if (nb == endNode) {
                    return "can be travelled";
                }
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    queue.offer(nb);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // In case of any unexpected runtime exception
        return "cannot be travelled";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return "Invalid date";
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return "Invalid date";
    }
    int monthInt, dayInt, yearInt;
    try {
        monthInt = Integer.parseInt(parts[0]);
        dayInt = Integer.parseInt(parts[1]);
        yearInt = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        return "Invalid date";
    }
    // Basic range checks
    if (monthInt < 1 || monthInt > 12) {
        return "Invalid date";
    }
    if (dayInt < 1 || dayInt > 31) {
        return "Invalid date";
    }
    try {
        java.time.LocalDate localDate = java.time.LocalDate.of(yearInt, monthInt, dayInt);
        String[] monthNames = {"January","February","March","April","May","June","July","August","September","October","November","December"};
        String monthName = monthNames[monthInt - 1];
        java.time.DayOfWeek dow = localDate.getDayOfWeek();
        String[] weekdayNames = {"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"};
        String weekdayName = weekdayNames[dow.getValue() - 1];
        return monthName + " " + dayInt + ", " + yearInt + " is a " + weekdayName;
    } catch (java.time.DateTimeException e) {
        return "Invalid date";
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null) {
        throw new IllegalArgumentException("nums cannot be null");
    }
    if (nums.length < 2) {
        throw new IllegalArgumentException("nums must contain at least two elements");
    }
    java.util.Map<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        Integer j = map.get(complement);
        if (j != null) {
            return new int[]{j, i};
        }
        map.put(nums[i], i);
    }
    throw new IllegalArgumentException("No valid pair found");
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is properly sorted
        if (nums[left] <= nums[mid]) { // left side sorted
            if (target >= nums[left] && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right side sorted
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int trim = n / 20; // floor of 5% of n
    if (trim * 2 >= n) {
        // Not enough elements to trim; return mean of whatever remains
        long sumAll = 0L;
        for (int v : arr) {
            sumAll += v;
        }
        return (double) sumAll / n;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0L;
    for (int i = trim; i < n - trim; i++) {
        sum += sorted[i];
    }
    return (double) sum / (n - 2 * trim);
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    if (arr.length % 2 != 0) {
        return false;
    }
    int n = arr.length;
    int[] freq = new int[k];
    for (int val : arr) {
        int r = ((val % k) + k) % k; // ensure non‑negative
        freq[r]++;
    }
    // remainder 0 must be even
    if (freq[0] % 2 != 0) {
        return false;
    }
    // if k is even, remainder k/2 must also be even
    if (k % 2 == 0) {
        int half = k / 2;
        if (freq[half] % 2 != 0) {
            return false;
        }
    }
    // check other remainders
    for (int r = 1; r < k / 2 + 1; r++) {
        int complement = (k - r) % k;
        if (r == complement) { // already handled when k is even
            continue;
        }
        if (freq[r] != freq[complement]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    try {
        if (n <= 0 || edges == null || hasApple == null || edges.length != n - 1 || hasApple.length != n) {
            throw new IllegalArgumentException("Invalid input");
        }
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            if (edge == null || edge.length != 2) {
                throw new IllegalArgumentException("Invalid edge format");
            }
            int u = edge[0];
            int v = edge[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                throw new IllegalArgumentException("Edge contains out-of-range node");
            }
            graph[u].add(v);
            graph[v].add(u);
        }
        final int[] totalTime = {0};

        java.util.function.BiFunction<Integer, Integer, Boolean> dfs = new java.util.function.BiFunction<Integer, Integer, Boolean>() {
            @Override
            public Boolean apply(Integer node, Integer parent) {
                boolean subtreeHasApple = hasApple[node];
                for (int neighbor : graph[node]) {
                    if (!neighbor.equals(parent)) {
                        boolean childHasApple = this.apply(neighbor, node);
                        if (childHasApple) {
                            totalTime[0] += 2;
                            subtreeHasApple = true;
                        }
                    }
                }
                return subtreeHasApple;
            }
        };

        dfs.apply(0, -1);
        return totalTime[0];
    } catch (Exception e) {
        return 0;
    }
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        if (c >= 'a' && c <= 'z') {
            freq[c - 'a']++;
        } else {
            // If the string may contain other characters, we ignore them
            // as the problem description implies only lowercase letters.
        }
    }
    StringBuilder sb = new StringBuilder(s.length());
    int total = s.length();

    while (total > 0) {
        // Forward pass: smallest to largest
        for (int i = 0; i < 26 && total > 0; i++) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                total--;
            }
        }
        // Backward pass: largest to smallest
        for (int i = 25; i >= 0 && total > 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                total--;
            }
        }
    }

    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) return false;
    int n = nums.length;
    long totalSum = 0;
    for (int num : nums) totalSum += num;
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        long target = totalSum * k / n;
        @SuppressWarnings("unchecked")
        java.util.Set<Long>[] subsets = new java.util.HashSet[k + 1];
        for (int i = 0; i <= k; i++) subsets[i] = new java.util.HashSet<>();
        subsets[0].add(0L);
        for (int num : nums) {
            long val = num;
            for (int j = Math.min(k - 1, n - 1); j >= 0; j--) {
                for (long s : subsets[j]) {
                    subsets[j + 1].add(s + val);
                }
            }
            if (subsets[k].contains(target)) return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int fromPrev = dp[i - 1] + cost[i - 1];
        int fromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(fromPrev, fromPrevPrev);
    }
    return dp[n];
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null) {
        return 0;
    }
    String[] morse = {
        ".-","-...","-.-.","-..",".","..-.", "--.", "....", "..", ".---",
        "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", "...",
        "-", "..-", "...-", ".--", "-..-", "-.--", "--.."
    };
    Set<String> uniqueSet = new HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } // ignore other characters
        }
        uniqueSet.add(sb.toString());
    }
    return uniqueSet.size();
}

public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || k < 0) {
        return false;
    }
    int n = s.length();
    if (k == 0) {
        // Only the empty string exists, which is trivially a substring
        return true;
    }
    if (n < k) {
        return false;
    }
    // If k is large, using an array of size 2^k may be infeasible.
    // For very large k, it's impossible to contain all 2^k codes in a string of length n.
    if (k > 23) { // 2^24 ~ 16 million, exceed typical memory of a boolean array in tight constraints
        // Use a Set to track seen codes
        java.util.HashSet<Integer> seen = new java.util.HashSet<>();
        int value = 0;
        for (int i = 0; i < k; i++) {
            value = (value << 1) | (s.charAt(i) - '0');
        }
        seen.add(value);
        for (int i = k; i < n; i++) {
            value = ((value << 1) & ((1 << k) - 1)) | (s.charAt(i) - '0');
            seen.add(value);
            if (seen.size() == (1 << k)) {
                return true;
            }
        }
        return seen.size() == (1 << k);
    }

    // Standard array-based solution for moderate k
    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int count = 0;
    int mask = totalCodes - 1;
    int value = 0;
    for (int i = 0; i < k; i++) {
        value = (value << 1) | (s.charAt(i) - '0');
    }
    if (!seen[value]) {
        seen[value] = true;
        count++;
    }
    for (int i = k; i < n; i++) {
        value = ((value << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[value]) {
            seen[value] = true;
            count++;
            if (count == totalCodes) {
                return true;
            }
        }
    }
    return count == totalCodes;
}

