public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int insertions = 0;
    int balance = 0; // number of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // Need to insert an opening parenthesis before this ')'
                insertions++;
            } else {
                // Match with an existing '('
                balance--;
            }
        } else {
            // Invalid character; skip or optionally throw exception
            // For robustness, we skip it
        }
    }
    // Any remaining unmatched '(' require a ')' insertion
    insertions += balance;
    return insertions;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int i0 = n / 2 + n % 2; // first index with arr[i] > n
    int m = n - i0; // number of surplus elements
    if (m <= 0) {
        return 0;
    }
    long sumI = ((long) i0 + (n - 1)) * m / 2; // sum of indices from i0 to n-1
    long surplus = 2L * sumI - (long) (n - 1) * m;
    return (int) surplus;
}

