public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int currentMax = nums[0];
    int maxSum = nums[0];
    int currentMin = nums[0];
    int minSum = nums[0];

    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        currentMax = Math.max(val, currentMax + val);
        maxSum = Math.max(maxSum, currentMax);

        currentMin = Math.min(val, currentMin + val);
        minSum = Math.min(minSum, currentMin);
    }

    // The maximum absolute sum is the larger of the largest positive sum
    // and the absolute value of the most negative sum.
    return Math.max(maxSum, Math.abs(minSum));
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers not exceeding k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int sz = fibs.size();
        long next = (long) fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) {
            break;
        }
        fibs.add((int) next);
    }

    int count = 0;
    int remaining = k;
    // Greedy selection from largest to smallest
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> big = new java.util.ArrayList<>();
    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                big.add(other);
            }
        }
    }
    int count = 0;
    for (int val : small) {
        count++;
        if (count == k) {
            return val;
        }
    }
    java.util.Collections.reverse(big);
    for (int val : big) {
        count++;
        if (count == k) {
            return val;
        }
    }
    return -1;
}

