public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int maxCount = 0;
    // There are n-1 possible split positions
    int limit = 1 << (n - 1);
    for (int mask = 0; mask < limit; mask++) {
        HashSet<String> seen = new HashSet<>();
        int start = 0;
        boolean valid = true;
        int count = 0;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) { // split after position i
                String sub = s.substring(start, i + 1);
                if (!seen.add(sub)) {
                    valid = false;
                    break;
                }
                start = i + 1;
                count++;
            }
        }
        if (!valid) {
            continue;
        }
        // add the last substring
        String last = s.substring(start, n);
        if (!seen.add(last)) {
            continue;
        }
        count++;
        if (count > maxCount) {
            maxCount = count;
        }
    }
    return maxCount;
}

