            depth++;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    long maxSum = 26L * n;
    if (k < n || k > maxSum) {
        throw new IllegalArgumentException("k is out of valid range for the given n");
    }
    char[] chars = new char[n];
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    int remaining = k - n; // additional value needed beyond all 'a's
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        chars[i] = (char) (chars[i] + add);
        remaining -= add;
    }
    return new String(chars);
}

