public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bitCount[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (high < 0 || low > high) {
        return result;
    }
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long child = num * 10 + (lastDigit - 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
        if (lastDigit < 9) {
            long child = num * 10 + (lastDigit + 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long pos = 1;
    while (pos <= n) {
        long high = n / (pos * 10);
        long cur = (n / pos) % 10;
        long low = n % pos;
        if (cur == 0) {
            count += high * pos;
        } else if (cur == 1) {
            count += high * pos + low + 1;
        } else {
            count += (high + 1) * pos;
        }
        if (pos > Long.MAX_VALUE / 10) {
            break; // prevent overflow on next multiplication
        }
        pos *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // Power of two is only defined for positive integers.
    if (n <= 0) {
        return false;
    }
    // A number that is a power of two has exactly one bit set.
    // Thus n & (n - 1) should be zero.
    return (n & (n - 1)) == 0;
}

