public static int longestLine(int[][] mat) {
    // Validate input
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;

    // Previous row direction arrays
    int[] prevV = new int[n];
    int[] prevDiag = new int[n];
    int[] prevAnti = new int[n];

    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        int[] curV = new int[n];
        int[] curDiag = new int[n];
        int[] curAnti = new int[n];

        int horiz = 0;

        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                horiz = horiz + 1;

                // Vertical
                int vert = prevV[j] + 1;

                // Diagonal
                int diag = (j > 0 ? prevDiag[j - 1] : 0) + 1;

                // Anti-diagonal
                int anti = (j < n - 1 ? prevAnti[j + 1] : 0) + 1;

                // Update current arrays
                curV[j] = vert;
                curDiag[j] = diag;
                curAnti[j] = anti;

                // Update maximum length
                int localMax = Math.max(Math.max(horiz, vert), Math.max(diag, anti));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                // If the cell is 0, all directions reset to 0
                horiz = 0;
                curV[j] = 0;
                curDiag[j] = 0;
                curAnti[j] = 0;
            }
        }

        // Prepare for next row
        prevV = curV;
        prevDiag = curDiag;
        prevAnti = curAnti;
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long value = Math.abs((long) n); // use long to handle Integer.MIN_VALUE
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    while (value > 0) {
        sb.append(value % 10);
        value /= 10;
        digitCount++;
        if (value > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    boolean[][] ok = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                int sum = arr[i] + arr[j];
                int r = (int) Math.sqrt(sum);
                ok[i][j] = r * r == sum;
            }
        }
    }
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int nxt = 0; nxt < n; nxt++) {
                if ((mask & (1 << nxt)) != 0) continue;
                if (!ok[last][nxt]) continue;
                if (nxt > 0 && arr[nxt] == arr[nxt - 1] && ( (mask & (1 << (nxt - 1))) == 0)) continue;
                int newMask = mask | (1 << nxt);
                dp[newMask][nxt] += cur;
            }
        }
    }
    long ans = 0;
    for (int i = 0; i < n; i++) ans += dp[fullMask][i];
    return (int) ans;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    try {
        int n = heights.length;
        java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
        int maxArea = 0;
        for (int i = 0; i <= n; i++) {
            int curHeight = (i == n) ? 0 : heights[i];
            while (!stack.isEmpty() && curHeight <= heights[stack.peek()]) {
                int h = heights[stack.pop()];
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                int area = h * width;
                if (area > maxArea) {
                    maxArea = area;
                }
            }
            stack.push(i);
        }
        return maxArea;
    } catch (Exception e) {
        // In case of unexpected runtime issues, return 0 as a safe default.
        return 0;
    }
}

public static int[] diagonalOrder(int[][] mat) {
    try {
        if (mat == null || mat.length == 0) {
            return new int[0];
        }
        int m = mat.length;
        int n = mat[0].length;
        if (n == 0) {
            return new int[0];
        }
        // Validate all rows for consistent length
        for (int i = 1; i < m; i++) {
            if (mat[i] == null || mat[i].length != n) {
                return new int[0];
            }
        }
        int total = m * n;
        int[] res = new int[total];
        int idx = 0;
        for (int k = 0; k <= m + n - 2; k++) {
            int startRow = Math.max(0, k - (n - 1));
            int endRow = Math.min(m - 1, k);
            if (k % 2 == 0) {
                for (int row = endRow; row >= startRow; row--) {
                    res[idx++] = mat[row][k - row];
                }
            } else {
                for (int row = startRow; row <= endRow; row++) {
                    res[idx++] = mat[row][k - row];
                }
            }
        }
        return res;
    } catch (Exception e) {
        return new int[0];
    }
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // digits are in non‑increasing order, no greater permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] current = new char[n];
    char[][] pairs = {
        {'0', '0'}, {'1', '1'}, {'8', '8'}, {'6', '9'}, {'9', '6'}
    };

    build(n, 0, n - 1, current, pairs, result);
    result.sort(String::compareTo);
    return result;
}

private static void build(int n, int left, int right, char[] current,
                           char[][] pairs, List<String> result) {
    if (left > right) {
        result.add(new String(current));
        return;
    }

    if (left == right) {
        // Middle position in odd length
        char[] mids = {'0', '1', '8'};
        for (char mid : mids) {
            current[left] = mid;
            result.add(new String(current));
        }
        return;
    }

    for (char[] pair : pairs) {
        if (left == 0 && pair[0] == '0' && n > 1) {
            // Skip numbers with leading zero (unless the number itself is 0)
            continue;
        }
        current[left] = pair[0];
        current[right] = pair[1];
        build(n, left + 1, right - 1, current, pairs, result);
    }
}

public static boolean isBoomerang(int[][] points) {
    try {
        if (points == null || points.length != 3) {
            return false;
        }
        for (int i = 0; i < 3; i++) {
            if (points[i] == null || points[i].length != 2) {
                return false;
            }
        }
        int x0 = points[0][0], y0 = points[0][1];
        int x1 = points[1][0], y1 = points[1][1];
        int x2 = points[2][0], y2 = points[2][1];
        long cross = (long)(x1 - x0) * (y2 - y0) - (long)(y1 - y0) * (x2 - x0);
        return cross != 0;
    } catch (Exception e) {
        return false;
    }
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int count = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char current = s.charAt(i);
        if (current == prev) {
            count++;
        } else {
            if (count > max) {
                max = count;
            }
            count = 1;
            prev = current;
        }
    }
    return Math.max(max, count);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int current = 1;
    int count = 0;
    while (count < n) {
        result.add(current);
        count++;
        long next = (long) current * 10;
        if (next <= n) {
            current = (int) next;
        } else {
            while ((current % 10 == 9) || (((long) current + 1) > n)) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int sum = 0;
    java.util.HashSet<Integer> seen = new java.util.HashSet<>();
    java.util.HashSet<Integer> duplicates = new java.util.HashSet<>();
    for (int value : nums) {
        if (duplicates.contains(value)) {
            continue; // already counted as duplicate, skip
        }
        if (seen.contains(value)) {
            // second occurrence: remove the previously added value from sum
            sum -= value;
            duplicates.add(value);
        } else {
            seen.add(value);
            sum += value;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // worst case: all 1^2
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

